import * as React from "react"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};


/**
 * POLAROID WALL
 * A responsive, self-arranging grid of realistic polaroid photos.
 *
 * - Only the WIDTH of this component is meant to be resized by hand in Framer.
 *   Height is fully derived from content (rows × polaroid height), so it should
 *   be left on "Auto" in the layout panel (see annotations below).
 * - Each polaroid keeps a strict 3:4 outer ratio and a strict 1:1 photo slot,
 *   both driven by CSS aspect-ratio, so they stay correct at any width, on any
 *   device, and while resizing — no pixel math that can drift or break.
 * - "Per row" + "Gap" are the only sizing controls. The grid computes each
 *   polaroid's width from those two values and the available frame width;
 *   the polaroid never sets its own size directly.
 */

interface PolaroidItem {
    image?: any
    caption?: string
}

interface Props {
    columns: number
    gap: number
    randomizeRotation: boolean
    maxRotation: number
    vintage: boolean
    photos: PolaroidItem[]
    captionFont: React.CSSProperties
    captionColor: string
    enableSound: boolean
    soundFile?: { url?: string }
    volume: number
    style?: React.CSSProperties
}

// Deterministic pseudo-random generator (mulberry32), seeded by index.
// Same index always yields the same "random" values — no flicker on re-render.
function seededRandom(seed: number) {
    let t = (seed += 0x6d2b79f5)
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

// Subtle film-grain texture as an inline SVG data URI (no network request).
const GRAIN_SVG =
    "data:image/svg+xml;utf8," +
    encodeURIComponent(
        `<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%' height='100%' filter='url(#n)'/></svg>`
    )

// Built-in default hover/tap sound (embedded so it works with zero setup).
// Users can still override it with their own file via the "Custom tick" control.
const DEFAULT_TICK_SOUND =
    "data:audio/mpeg;base64,"

// Lazily-created, shared AudioContext for the default synthesized tick.
let sharedAudioCtx: AudioContext | null = null

function playSynthTick(volume: number) {
    if (typeof window === "undefined") return
    try {
        const Ctx = window.AudioContext || (window as any).webkitAudioContext
        if (!Ctx) return
        if (!sharedAudioCtx) sharedAudioCtx = new Ctx()
        if (sharedAudioCtx.state === "suspended") sharedAudioCtx.resume()

        const now = sharedAudioCtx.currentTime
        const osc = sharedAudioCtx.createOscillator()
        const gain = sharedAudioCtx.createGain()
        osc.type = "square"
        osc.frequency.setValueAtTime(1400, now)
        osc.frequency.exponentialRampToValueAtTime(900, now + 0.03)
        gain.gain.setValueAtTime(0.12 * volume, now)
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05)
        osc.connect(gain)
        gain.connect(sharedAudioCtx.destination)
        osc.start(now)
        osc.stop(now + 0.06)
    } catch (e) {
        // Fail silently — a missing tick sound should never break the layout.
    }
}

function PolaroidCard({
    item,
    index,
    randomizeRotation,
    maxRotation,
    vintage,
    captionFont,
    captionColor,
    enableSound,
    soundFile,
    volume,
}: {
    item: PolaroidItem
    index: number
    randomizeRotation: boolean
    maxRotation: number
    vintage: boolean
    captionFont: React.CSSProperties
    captionColor: string
    enableSound: boolean
    soundFile?: { url?: string }
    volume: number
}) {
    const r1 = seededRandom(index * 13 + 1)
    const r2 = seededRandom(index * 29 + 7)
    const r3 = seededRandom(index * 53 + 3)

    const rotation = randomizeRotation ? (r1 * 2 - 1) * maxRotation : 0
    const brightness = 0.97 + r2 * 0.06 // 0.97 – 1.03, subtle per-card variance
    const hueRotate = (r3 * 2 - 1) * 3 // -3deg to 3deg, keeps paper from looking uniform
    const sepia = vintage ? 0.12 + r2 * 0.08 : 0

    const customAudioRef = React.useRef<HTMLAudioElement | null>(null)

    React.useEffect(() => {
        const src = soundFile?.url || DEFAULT_TICK_SOUND
        customAudioRef.current = new Audio(src)
        customAudioRef.current.preload = "auto"
    }, [soundFile?.url])

    const triggerSound = () => {
        if (!enableSound) return
        const audio = customAudioRef.current
        if (audio) {
            try {
                audio.volume = Math.min(1, Math.max(0, volume))
                audio.currentTime = 0
                audio.play().catch(() => playSynthTick(volume))
            } catch (e) {
                playSynthTick(volume)
            }
        } else {
            playSynthTick(volume)
        }
    }

    // Hover triggers the sound on desktop; touch devices have no hover, so a
    // tap (pointerdown) fires the same sound there. No size change either way.
    const handlePointerEnter = (e: React.PointerEvent) => {
        if (e.pointerType === "touch") return
        triggerSound()
    }
    const handlePointerDown = (e: React.PointerEvent) => {
        if (e.pointerType !== "touch") return
        triggerSound()
    }

    return (
        <div
            onPointerEnter={handlePointerEnter}
            onPointerDown={handlePointerDown}
            style={{
                position: "relative",
                width: "100%",
                aspectRatio: "3 / 4",
                transform: `rotate(${rotation}deg)`,
                transformOrigin: "center center",
                cursor: "pointer",
                touchAction: "manipulation",
            }}
        >
            {/* static layer: filter, shadow, background */}
            <div
                style={{
                    position: "relative",
                    width: "100%",
                    height: "100%",
                    borderRadius: 2,
                    background:
                        "linear-gradient(155deg, #fdfdfc 0%, #f7f6f2 55%, #efeee9 100%)",
                    filter: `brightness(${brightness}) hue-rotate(${hueRotate}deg) sepia(${sepia})`,
                    boxShadow:
                        "0 1px 1px rgba(20,15,10,0.10), 0 3px 6px rgba(20,15,10,0.10), 0 10px 18px -4px rgba(20,15,10,0.18), 0 22px 34px -12px rgba(20,15,10,0.22)",
                    display: "flex",
                    flexDirection: "column",
                    padding: "6% 6% 0 6%",
                    boxSizing: "border-box",
                    overflow: "hidden",
                }}
            >
                {/* film grain */}
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        backgroundImage: `url("${GRAIN_SVG}")`,
                        backgroundSize: "140px 140px",
                        opacity: 0.035,
                        mixBlendMode: "multiply",
                        pointerEvents: "none",
                    }}
                />
                {/* sheen / light falloff */}
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        background:
                            "linear-gradient(135deg, rgba(255,255,255,0.5) 0%, rgba(255,255,255,0) 30%, rgba(0,0,0,0) 70%, rgba(0,0,0,0.04) 100%)",
                        pointerEvents: "none",
                    }}
                />

                {/* photo slot — always 1:1, sits inside top+side padding */}
                <div
                    style={{
                        position: "relative",
                        width: "100%",
                        aspectRatio: "1 / 1",
                        background: "#1a1a1a",
                        boxShadow: "inset 0 1px 3px rgba(0,0,0,0.5)",
                        overflow: "hidden",
                        flexShrink: 0,
                    }}
                >
                    {item?.image?.src ? (
                        <img
                            src={item.image.src}
                            srcSet={item.image.srcSet}
                            alt={item.image.alt || "Polaroid photo"}
                            style={{
                                width: "100%",
                                height: "100%",
                                objectFit: "cover",
                                objectPosition: "center",
                                display: "block",
                            }}
                        />
                    ) : (
                        <div
                            style={{
                                width: "100%",
                                height: "100%",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                color: "rgba(255,255,255,0.25)",
                                fontSize: 12,
                                fontFamily: "system-ui, sans-serif",
                            }}
                        >
                            Add photo
                        </div>
                    )}
                </div>

                {/* caption strip — the larger bottom margin, sized by whatever space is left */}
                <div
                    style={{
                        flex: 1,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        minHeight: 0,
                    }}
                >
                    {item?.caption ? (
                        <span
                            style={{
                                fontFamily:
                                    "'Segoe Print', 'Bradley Hand', 'Comic Sans MS', cursive",
                                fontSize: "clamp(10px, 4.5%, 16px)",
                                lineHeight: 1.2,
                                ...captionFont,
                                color: captionColor,
                                textAlign: "center",
                                padding: "0 4%",
                            }}
                        >
                            {item.caption}
                        </span>
                    ) : null}
                </div>
            </div>
        </div>
    )
}

/**
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight auto
 */
export default function PolaroidWall(props: Props) {
    const {
        columns,
        gap,
        randomizeRotation,
        maxRotation,
        vintage,
        photos,
        captionFont,
        captionColor,
        enableSound,
        soundFile,
        volume,
        style,
    } = props

    return (
        <div
            style={{
                ...style,
                width: "100%",
                display: "grid",
                gridTemplateColumns: `repeat(${Math.max(1, columns)}, 1fr)`,
                gap: gap,
                alignItems: "start",
            }}
        >
            {photos.map((item, i) => (
                <PolaroidCard
                    key={i}
                    item={item}
                    index={i}
                    randomizeRotation={randomizeRotation}
                    maxRotation={maxRotation}
                    vintage={vintage}
                    captionFont={captionFont}
                    captionColor={captionColor}
                    enableSound={enableSound}
                    soundFile={soundFile}
                    volume={volume}
                />
            ))}
        </div>
    )
}

PolaroidWall.displayName = "Polaroid Wall"

addPropertyControls(PolaroidWall, {
    columns: {
        type: ControlType.Number,
        title: "Per row",
        defaultValue: 3,
        min: 1,
        max: 12,
        step: 1,
    },
    gap: {
        type: ControlType.Number,
        title: "Gap",
        defaultValue: 16,
        min: 0,
        max: 100,
        step: 1,
        unit: "px",
    },
    randomizeRotation: {
        type: ControlType.Boolean,
        title: "Scatter tilt",
        defaultValue: true,
    },
    maxRotation: {
        type: ControlType.Number,
        title: "Max tilt",
        defaultValue: 3,
        min: 0,
        max: 15,
        step: 0.5,
        unit: "°",
        hidden: (props: Props) => !props.randomizeRotation,
    },
    vintage: {
        type: ControlType.Boolean,
        title: "Vintage tone",
        defaultValue: true,
    },
    photos: {
        type: ControlType.Array,
        title: "Photos",
        control: {
            type: ControlType.Object,
            controls: {
                image: { type: ControlType.ResponsiveImage, title: "Image" },
                caption: {
                    type: ControlType.String,
                    title: "Caption",
                    defaultValue: "",
                },
            },
        },
        defaultValue: [{}, {}, {}, {}, {}, {}],
    },
    captionFont: {
        type: ControlType.Font,
        title: "Caption font",
        controls: "extended",
        defaultValue: {
            fontFamily: "Segoe Print, Bradley Hand, Comic Sans MS, cursive",
        },
    },
    captionColor: {
        type: ControlType.Color,
        title: "Caption color",
        defaultValue: "#3a352f",
    },
    enableSound: {
        type: ControlType.Boolean,
        title: "Hover sound",
        defaultValue: true,
    },
    volume: {
        type: ControlType.Number,
        title: "Volume",
        defaultValue: 0.5,
        min: 0,
        max: 1,
        step: 0.01,
        displayStepper: false,
        hidden: (props: Props) => !props.enableSound,
    },
    soundFile: {
        type: ControlType.File,
        title: "Custom tick",
        description: "Optional — overrides the built-in tick sound",
        allowedFileTypes: [
            "audio/mpeg",
            "audio/mp3",
            "audio/wav",
            "audio/ogg",
            "audio/m4a",
            "audio/x-m4a",
        ],
        hidden: (props: Props) => !props.enableSound,
    },
})
